 fa_case('Native runtime receives the published Study date format without rewriting its assessment',function(){global $native;foreach(array(false,true) as $long){$x=fa_study($long,false,false,false,array(),'DD/MM/YYYY');$f=fa_frame($x,$long);$offer=R\NativeBridge::offer($f);$n=$native->view($offer['execution_id']);fa_assert($n['study_date_format']==='DD/MM/YYYY');fa_assert(!isset($n['definition']['protocol_metadata']['date_format']));}});
