 foreach($owned as $study)try{$svc->deleteStudy($study,'ELIMINAR '.$study);}catch(Throwable $e){$failures++;echo 'FAIL cleanup '.$e->getMessage()."\n";}
 if(isset($nv))$native->store->db->query($native->store->prepare('DELETE FROM '.$native->store->table('versions').' WHERE id=%s',$nv['version_id']));if(isset($definition))delete_option(EIPSI\AssessmentEditor\Repository::PREFIX.$definition['id']);if($priorEnv===false)putenv('EIPSI_STUDY_ENGINE_KEYRING');else putenv('EIPSI_STUDY_ENGINE_KEYRING='.$priorEnv);if($priorIp===null)unset($_SERVER['REMOTE_ADDR']);else $_SERVER['REMOTE_ADDR']=$priorIp;$_COOKIE=$priorCookies;unset($_SERVER['HTTP_X_FORWARDED_FOR']);
